{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C54", "C57", "C62", "C64", "C53", "C55", "C56", "C58"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C54", "C57", "C62", "C64", "C53", "C55", "C56", "C58"],
  "claims": [
    {
      "claim": "L4 human absorption records for close morphinan analogs show complete or near-complete intestinal absorption (dextromethorphan complete; codeine Fa 95% and >90% by urinary excretion), supporting high absorption for the query's morphinan scaffold.",
      "card_ids": ["C54", "C57", "C62", "C64"]
    },
    {
      "claim": "Rat fraction-absorbed values of 0.92–0.99 for a polar morphine-6-glucuronide indicate that even polar morphinans can be well absorbed, mitigating concern that the query's low neutral fraction would limit absorption.",
      "card_ids": ["C53", "C55", "C56", "C58"]
    },
    {
      "claim": "No L4 record measures systemic F or involves hydromorphone/rifampin, so these records support only the absorption component; the high prediction is retained because no affirmative evidence indicates F < 20% under rifampin.",
      "card_ids": ["C54", "C57", "C62", "C64"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C54", "C57", "C62", "C64", "C53", "C55", "C56", "C58"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or matched oral/IV exposure measurement for hydromorphone under rifampin co-treatment.",
    "No hydromorphone-specific fraction-absorbed or permeability measurement; L4 records are for close analogs or a glucuronide.",
    "No quantification of rifampin's induction of first-pass glucuronidation or intestinal efflux for hydromorphone.",
    "No solubility/dissolution data under the rifampin co-treatment condition."
  ],
  "decision_summary": "Retained and modestly strengthened high (F >= 20%) because L4 provides supportive evidence of high intestinal absorption for morphinan analogs, while no affirmative evidence indicates F < 20% under rifampin; confidence is moderate given the absence of direct hydromorphone/rifampin F data."
}

